// js/icons.js
// Diccionario de iconos de la app (PNG en base64) + utilidades de
// presentacion compartidas (appIcon para insertar un icono, escapeHtml
// para evitar XSS al insertar texto dinamico). Este archivo no depende
// de ningun otro modulo de la app; debe cargarse antes de los demas
// scripts porque ellos usan appIcon()/escapeHtml() globalmente.

      window.APP_ICONS = {
        bus: "data:image/png;base64,",
        smartphone: "data:image/png;base64,",
        settings: "data:image/png;base64,",
        search: "data:image/png;base64,",
        clock: "data:image/png;base64,",
        map: "data:image/png;base64,",
        shieldCheck: "data:image/png;base64,",
        gift: "data:image/png;base64,",
        mapPin: "data:image/png;base64,",
        bell: "data:image/png;base64,",
        building: "data:image/png;base64,",
        plus: "data:image/png;base64,",
        rocket: "data:image/png;base64,",
        flag: "data:image/png;base64,",
        star: "data:image/png;base64,",
        logout: "data:image/png;base64,",
      };

      // Genera un <img> a partir del diccionario de iconos de la app.
      // size: tamano en px (cuadrado). className: clases css opcionales.
      window.appIcon = function(name, size, className) {
        size = size || 20;
        className = className || '';
        var src = window.APP_ICONS[name] || '';
        return '<img src="' + src + '" alt="" class="app-icon ' + className + '" style="width:' + size + 'px;height:' + size + 'px;vertical-align:middle;" />';
      };

      // Escapa caracteres peligrosos antes de insertar texto via innerHTML.
      // Cualquier dato que venga de Firebase (nombre de empresa, placa,
      // nombre de conductor, etc.) debe pasar por aqui para evitar XSS:
      // si alguien registra una empresa con un nombre que contiene
      // codigo de script o atributos como onerror=, esto lo neutraliza
      // dejandolo como texto plano en vez de codigo ejecutable.
      window.escapeHtml = function(value) {
        if (value === null || value === undefined) return '';
        return String(value)
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#39;');
      };
